--
-- Table structure for table `episode_alternate_titles`
--

CREATE TABLE `episode_alternate_titles` (
  `id` smallint(5) UNSIGNED NOT NULL COMMENT 'Unique ID',
  `show_id` tinyint(2) UNSIGNED DEFAULT NULL COMMENT 'Show ID',
  `season_id` tinyint(3) UNSIGNED DEFAULT NULL COMMENT 'Season ID',
  `episode_id` smallint(4) UNSIGNED DEFAULT NULL COMMENT 'Episode ID',
  `country` enum('Denmark','Finland','Sweden','New Zealand','Norway','Portugal') COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Country',
  `platform` enum('MTV Katsomo','SVT Play','TV2 Play','TVNZ+','Discovery+ Norge','RTP Play','TV4') COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Streaming platform',
  `title` varchar(128) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Episode title on platform',
  `translation` varchar(128) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'English translation of platform title',
  `notes` varchar(512) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Contextual and translation notes'
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

