INSERT INTO `episode_alternate_titles` (`id`, `show_id`, `season_id`, `episode_id`, `country`, `platform`, `title`, `translation`, `notes`) VALUES
(1, 3, 14, 86, 'Finland', 'MTV Katsomo', 'Mediaanibuddha', 'Median Buddha', 'This is a reference to the \'Draw the median Buddha\' task.'),
(2, 3, 14, 87, 'Finland', 'MTV Katsomo', 'Pieni präntti', 'Small print', 'It\'s unclear what this might be a reference to - perhaps the rule in the \'Paint a portrait of the Taskmaster without touching the red mat\' task?'),
(3, 3, 14, 88, 'Finland', 'MTV Katsomo', 'Sylttyä ja vadelmamehua', 'Brawn and raspberry juice', 'This is a reference to the \'Write down the ingredients the Icelander wants / Make a meal using your ingredients\' and \'Pour 235ml of raspberry juice\' tasks.'),
(4, 3, 14, 89, 'Finland', 'MTV Katsomo', 'Majoneesikammo', 'Mayonnaise phobia', 'This is a reference to the \'Open the jar of mayonnaise\' task.'),
(5, 3, 14, 90, 'Finland', 'MTV Katsomo', 'Oveluudella voittoon', 'Winning with cunning', 'It\'s unclear what this might be a reference to.'),
(6, 3, 14, 91, 'Finland', 'MTV Katsomo', 'Muistihirmu', 'Mnemonist', 'This is a reference to the \'Memorise the code\' task.'),
(7, 3, 14, 92, 'Finland', 'MTV Katsomo', 'Koiria ja ketsuppia', 'Dogs and ketchup', 'This is a reference to the \'Persuade three dogs to stand on the mat\' and \'Get ketchup as far along a roll of paper as possible\' tasks.'),
(8, 3, 14, 93, 'Finland', 'MTV Katsomo', 'Pullaa ja painonnousua', 'Buns and weight gain', 'This is a reference to the \'Get the bun to David in the fewest steps\' and \'Gain the most weight\' tasks.'),
(9, 3, 15, 98, 'Finland', 'MTV Katsomo', 'Kirosanoja ja katapultteja', 'Cursewords and catapults', 'This is a reference to the \'Invent a new profanity\' and \'Make a coconut-flinging machine\' tasks.'),
(10, 3, 15, 99, 'Finland', 'MTV Katsomo', 'Keiloja tai taikoja', 'Pins or magic', 'This is a reference to the \'Knock over the fewest bowling pins\' and \'Impress a stranger with a magic trick\' tasks.'),
(11, 3, 15, 100, 'Finland', 'MTV Katsomo', 'Viisaasti vesillä', 'Water wise', 'This might be a reference to the \'Build a boat for David\' task.'),
(12, 3, 15, 101, 'Finland', 'MTV Katsomo', 'Palloja ja ankkoja', 'Balls and ducks', 'This is a reference to the \'Get the most balls into the goal\' and \'Place all the rubber ducks in the bath tub\' tasks.'),
(13, 3, 15, 102, 'Finland', 'MTV Katsomo', 'Rakkautta ja kanelipullia', 'Love and cinnamon buns', 'This is a reference to the \'Declare your love for the Taskmaster\' and \'Bake the largest cinnamon bun\' tasks.'),
(14, 3, 15, 103, 'Finland', 'MTV Katsomo', 'Revanssi', 'Rematch', 'Since the first season of Bäst i Test is not on MTV Katsomo, this episode would have been the first time that Finnish viewers would have seen a previous contestant (Marika Carlsson) return to the show in an attempt to redeem themself.'),
(15, 3, 15, 104, 'Finland', 'MTV Katsomo', 'Kohti korkeuksia', 'Upwards', 'This is presumably a reference to the \'Get as high as possible\' task.'),
(16, 3, 15, 246, 'Finland', 'MTV Katsomo', 'Bonusjakso', 'Bonus episode', NULL),
(17, 3, 16, 105, 'Finland', 'MTV Katsomo', 'Hälytysvalmiudessa', 'On alert', 'This is presumably a reference to the \'Put on overalls and lie on the ground when the siren sounds\' task.'),
(18, 3, 16, 106, 'Finland', 'MTV Katsomo', 'Syke nousuun', 'Pulse-pounding', 'This is a reference to the \'Raise David’s heart rate\' task.'),
(19, 3, 16, 107, 'Finland', 'MTV Katsomo', 'Hankala pizzatilaus', 'Difficult pizza order', 'This is a reference to the \'Order a pizza without using certain words\' task.'),
(20, 3, 16, 108, 'Finland', 'MTV Katsomo', 'Suur pullaryöstö', 'The Great Bun Robbery', 'This is a reference to the \'Steal the world’s best bun\' task, and also possibly a reference to The Great Train Robbery (a real crime in which £2.3 million was stolen from a Royal Mail train in England, in 1963).'),
(21, 3, 16, 109, 'Finland', 'MTV Katsomo', 'Paras cliffhanger', 'The best cliffhanger', 'This is a reference to the \'Make a soap opera cliffhanger\' task.'),
(22, 3, 16, 110, 'Finland', 'MTV Katsomo', 'Poliisi poliisi, potturiisi', 'Police police, potato rice', 'This is a reference to the \'Do something without police permission\' task.'),
(23, 3, 16, 111, 'Finland', 'MTV Katsomo', 'Keilailua ja moukarinheittoa', 'Bowling and hammer throwing', 'This is a reference to the \'Bowl over and then set back up many items\' and \'Throw the sledgehammer the third longest distance\' tasks.'),
(24, 3, 16, 112, 'Finland', 'MTV Katsomo', 'Teetä ja sokkopyöräilyä', 'Tea and blind cycling', 'This is a reference to the \'Invite David to tea\' and \'Blindly ride a tricycle around a course\' tasks.'),
(25, 3, 16, 113, 'Finland', 'MTV Katsomo', 'Paljon melua tyhjästä', 'Much ado about nothing', 'It\'s unclear what this might be a reference to.'),
(26, 3, 16, 247, 'Finland', 'MTV Katsomo', 'Hyviä ja huonoja ideoita', 'Good and bad ideas', 'It\'s unclear what this might be a reference to.'),
(27, 3, 33, 237, 'Finland', 'MTV Katsomo', 'Järkeä vai ei?', 'Does it make sense or not?', 'It\'s unclear what this might be a reference to.'),
(28, 3, 33, 238, 'Finland', 'MTV Katsomo', 'Luovaa ajattelua', 'Creative thinking', 'It\'s unclear what this might be a reference to.'),
(29, 3, 33, 239, 'Finland', 'MTV Katsomo', 'Kaksintaistelu', 'Duel', 'This is a reference to the \'Duel with David\' task.'),
(30, 3, 33, 240, 'Finland', 'MTV Katsomo', 'Hedelmiä kerrakseen', 'A lot of fruit', 'This is probably a reference to the episode prize - a large fruit basket - and the \'Ingest the watermelon\' and \'Don\'t get fruit on the pizza\' tasks.'),
(31, 3, 33, 241, 'Finland', 'MTV Katsomo', 'Keppihevostelua', 'Stick horse riding', 'This is a reference to the \'Predict the outcome of a hobby horse race\' task.'),
(32, 3, 33, 242, 'Finland', 'MTV Katsomo', 'Itsekehu kateissa', 'Missing boasting', 'This is probably a reference to the \'Converse with a stranger about yourself\' task.'),
(33, 3, 33, 243, 'Finland', 'MTV Katsomo', 'Rohkeus koetuksella', 'Courage tested', 'It\'s unclear what this might be a reference to.'),
(34, 3, 33, 244, 'Finland', 'MTV Katsomo', 'Soihtu ja yllätyslahja', 'A torch and a surprise gift', 'This is a reference to the \'Light the torch\' and \'Extinguish the torch\' tasks, and the \'Give David a package with unexpected contents\' task.'),
(35, 3, 33, 245, 'Finland', 'MTV Katsomo', 'Sokkokävelyä ja kahvinkeittoa', 'Blind walking and coffee brewing', 'This is a reference to the \'Travel as far as possible while blindfolded\' and \'Turn on the coffee machine from a distance\' tasks.'),
(36, 3, 33, 248, 'Finland', 'MTV Katsomo', 'Luovaa sekoilua', 'Creative mess', 'It\'s unclear what this might be a reference to.'),
(37, 4, 17, 114, 'Sweden', 'SVT Play', 'Löpa linan ut', 'Run the line out', 'This is a reference to the \'Unravel the reel of string\' task.'),
(38, 4, 17, 115, 'Sweden', 'SVT Play', 'Ute och elcyklar', 'Outdoors and electric bikes', 'This is a reference to the \'Move the playhouse as far as possible\' task.'),
(39, 4, 17, 116, 'Sweden', 'SVT Play', 'Bad och badankor', 'Baths and bath ducks', 'This is a reference to the \'Empty the bathtub\' task.'),
(40, 4, 17, 117, 'Sweden', 'SVT Play', 'Det omöjliga blinkrekordet', 'The impossible blinking record', 'This is a reference to the mind-blowing performances in the \'Don\'t blink\' task.'),
(41, 4, 17, 118, 'Sweden', 'SVT Play', 'Icke imponerande imponerande', 'Not impressively impressive', 'This is a reference to the \'Impress the Mayor\' task.'),
(42, 4, 17, 119, 'Sweden', 'SVT Play', 'Bortkastade poäng', 'Wasted points', 'It\'s unclear what this title might be a reference to. Perhaps Maria\'s disqualification in the \'Keep the most pineapples on your table\' task?'),
(43, 4, 17, 120, 'Sweden', 'SVT Play', 'Irriterande sorterande', 'Irritating sorting', 'This is a reference to the \'Develop an organisation system\' task. Also, both words rhyme, which makes it catchier.'),
(44, 4, 17, 121, 'Sweden', 'SVT Play', 'Norges roligaste hemmavideor', 'Norway\'s funniest home videos', 'This is a reference to the \'Stage a realistic home movie blooper\' task, and the US home video clips show <em>America\'s Funniest Home Videos</em>.'),
(45, 4, 17, 122, 'Sweden', 'SVT Play', 'Ana ugglor i luften', 'Sense owls in the air', 'This is a reference to the \'Make the owl fly as high as possible\' task, and a play on words on the Swedish idiom \'Ana ugglor i mossen\' (\'Sense owls in the marsh\'), which is similar to the English phrase \'to smell a rat\', meaning that one is suspicious.'),
(46, 4, 17, 123, 'Sweden', 'SVT Play', 'Bränna ljuset i båda ändarna', 'Burn the candle at both ends', 'This is a reference to the \'Melt the candle\' task.'),
(47, 4, 18, 124, 'Sweden', 'SVT Play', 'Förstå en finne', 'Understand a Finn', 'This is a reference to the \'Find out about the Finnish person\' task.'),
(48, 4, 18, 125, 'Sweden', 'SVT Play', 'Åka hiss i korthus', 'Ride the lift in a house of cards', 'This is a reference to both the \'Change your appearance in a lift\' and \'Build the tallest house of cards\' tasks.'),
(49, 4, 18, 126, 'Sweden', 'SVT Play', 'Inte dumpa skumpa', 'Don\'t dump bubbly', 'This is a reference to the \'Remove money from under a champagne tower\' task, but is worded so that it rhymes (with \'dumpa\' meaning \'dump\', and \'skumpa\' meaning \'bubbly\'), rather than the more literal \'Spill inte champagne\' (\'Don\'t spill champagne\').'),
(50, 4, 18, 127, 'Sweden', 'SVT Play', 'De vill ha puls', 'They want a pulse', 'This is a reference to the \'Ring the bell when your heart rate is 123\' task.'),
(51, 4, 18, 128, 'Sweden', 'SVT Play', 'Karuselltårta', 'Carousel cake', 'This is a reference to the \'Decorate the rotating cake\' task.'),
(52, 4, 18, 129, 'Sweden', 'SVT Play', 'Frakta vatten norrut', 'Transport water north', 'This is a straight reference to the \'Transport water north\' task.'),
(53, 4, 18, 130, 'Sweden', 'SVT Play', 'Imponera på en svensk', 'Impress a Swede', 'This is a reference to the \'Convince a Swede that you are the most famous contestant\' task.'),
(54, 4, 18, 131, 'Sweden', 'SVT Play', 'Citrontorn och smuggeldon', 'Lemon tower and contraband', 'This is a reference to the \'Make the tallest lemon tower\' and \'Smuggle objects without Olli seeing you\' tasks.'),
(55, 4, 18, 132, 'Sweden', 'SVT Play', 'Norsk dockteater', 'Norwegian puppet theatre', 'This is a reference to the \'Perform a thought-provoking puppet show\' task.'),
(56, 4, 18, 133, 'Sweden', 'SVT Play', 'Grand finale', NULL, 'This is simply a reference to the fact that this episode is the season finale. Not sure why they chose to reference this in only this particular season finale, rather than referencing one of the tasks, like they\'ve done for the others.'),
(57, 4, 19, 134, 'Sweden', 'SVT Play', 'Långloppsljus', 'Long race lights', 'As in the original Norwegian title, this is a reference to Jenny Skavlan\'s submission for the \'Something you have, but should not\' prize task, where she refers to turning on her high-beam lights when driving, but uses the unstranslatable compound word \'langrennslys\'. In Swedish, the equivalent  compound word is \'långloppsljus\'. The component parts of this word are \'lång\' (meaning \'long\'), \'lopp\' (meaning \'race\'), and \'sljus\' (meaning \'light\').'),
(58, 4, 19, 135, 'Sweden', 'SVT Play', 'Ta det lugnt med bollarna', 'Be careful with the balls', 'This is a reference to the \'Put the most balls in the tube\' task.'),
(59, 4, 19, 136, 'Sweden', 'SVT Play', 'Det har jag aldrig sagt', 'I\'ve never said that', 'This is a reference to the \'Write a word that you think Atle has never said\' task.'),
(60, 4, 19, 137, 'Sweden', 'SVT Play', 'Ute och cyklar', 'Out and cycling', 'The phrase \'Ute och cykla\' is a Swedish expression used to describe someone who\'s completely lost (mentally-speaking), in somewhat the same way that we might figuratively describe someone as \'lost at sea\' in English. Many Swedes cycle to let their minds drift, and therefore joke about being absent-minded when they are cycling. In this case, the phrase is also a reference to the \'Draw the biggest bike\' task.'),
(61, 4, 19, 138, 'Sweden', 'SVT Play', 'Dominohistorier', 'Domino stories', 'This is a straight translation of the original Norwegian title, which was what Jenny Skavlan suggested should be the subject of Linn Skåber\'s YouTube channel, during the \'Create the best domino effect\' task.'),
(62, 4, 19, 139, 'Sweden', 'SVT Play', 'Vart kör lådbilen?', 'Where does the boxcar go?', 'This is a reference to the \'Convince Atle that the car is going to backwards land\' task, in which there is a car made from a cardboard box.'),
(63, 4, 19, 140, 'Sweden', 'SVT Play', 'Rädda familjen', 'Save the family', 'This is a reference to the \'Save Olli\'s family\' task.'),
(64, 4, 19, 141, 'Sweden', 'SVT Play', 'Läs brevet 100 gånger', 'Read the letter 100 times', 'This is a straight translation of the original Norwegian title, which was a quote from Trond Fausa Aurvåg, during the \'Burn the string to ring the bell\' task.'),
(65, 8, 27, 180, 'Sweden', 'SVT Play', 'Glutenfri filosofi', 'Gluten-free philosophy', 'This is a reference to the \'Hit a piece of fruit with some bread\' task, in which one of the type of bread was gluten-free. Not sure where the philosophy comes into it, though.'),
(66, 8, 27, 181, 'Sweden', 'SVT Play', 'Nationalsånger med ånger', 'National anthems with regret', 'This is a reference to the \'Write and perform a national anthem\' task, and the regret that several of the contestants felt about their creations. Also, the words \'nationalsånger\' and \'ånger\' rhyme, which makes it catchy.'),
(67, 8, 27, 182, 'Sweden', 'SVT Play', 'Sexigast träd vinner', 'Sexiest tree wins', 'This is a direct reference to the task brief of the \'Make a tree sexy\' task.'),
(68, 8, 27, 183, 'Sweden', 'SVT Play', 'Omskuren morot', 'Circumcised carrot', 'This is a direct reference to the result of Angella Dravid\'s attempt at the \'Hide a vegetable completely inside another\' task, where she hid a brussels sprout in a carrot, and then commented that it looked \'circumcised\'.'),
(69, 8, 27, 184, 'Sweden', 'SVT Play', 'Den ursprungliga superspridaren', 'The original super-spreader', 'This is a translated direct quote from Madeleine Sami, in relation to her attempt at the \'Be as unhealthy as possible\' task, in which she had members of the production crew cough on her. After Leigh Hart commented that she\'d probably started the Covid-19 pandemic, she admitted that she was \"the original super-spreader\".'),
(70, 8, 27, 185, 'Sweden', 'SVT Play', 'Det är jag som är problemet', 'It is me who is the problem', 'This is a fairly straight translation of the original episode title, which was a quote from Guy Williams.'),
(71, 8, 27, 186, 'Sweden', 'SVT Play', 'En övertygande fejksemester', 'A convincing fake holiday', 'This is a reference to the \'Go on a convincing fake holiday\' task.'),
(72, 8, 27, 187, 'Sweden', 'SVT Play', 'Svettiga strumpor och depression', 'Sweaty socks and depression', 'This is a direct translation of the original episode title, which was a quote from Angella Dravid.'),
(73, 8, 27, 188, 'Sweden', 'SVT Play', 'En överraskande korv', 'A surprising sausage', 'This is a reference to the \'Make a surprisingly pleasant sausage\' task.'),
(74, 8, 27, 189, 'Sweden', 'SVT Play', 'Bäst i brott', 'Best in crime', 'This is a reference to the \'Commit a crime without breaking the law\' task.'),
