(216, 1, 11, 76, 'Finland', 'MTV Katsomo', 'Dokkari despootista', 'A documentary about a despot', NULL),
(217, 1, 11, 76, 'Sweden', 'SVT Play', 'Den högljudda mannen i den höga stolen', 'The loud man in the umpire chair ', 'This is a reference to Johnny Vegas\' performance in the \'Find the treasure / Make different, increasingly loud noises\' task.'),
(218, 1, 11, 76, 'Denmark', 'TV2 Play', 'En dokumentar om en despot', 'A documentary about a despot', NULL),
