(286, 1, 48, 315, 'Finland', 'MTV Katsomo', 'Arvaa kenkä', 'Guess the shoe', NULL),
(287, 1, 48, 316, 'Finland', 'MTV Katsomo', 'Vähän hykerryttää', 'Having a little chuckle', NULL),
(288, 1, 48, 317, 'Finland', 'MTV Katsomo', '75. kysymys', 'The 75th question', NULL),
