(290, 1, 48, 319, 'Finland', 'MTV Katsomo', 'Pakkoruotsia', 'Obligatory Swedish', NULL),
(291, 1, 48, 320, 'Finland', 'MTV Katsomo', 'Voi se olla vedettäväkin', 'It might be wind-up', NULL),
(292, 1, 55, 384, 'Finland', 'MTV Katsomo', 'Runko, siivet', 'The chassis, the wings', NULL),
(293, 1, 55, 385, 'Finland', 'MTV Katsomo', 'Suunnaton valtavuus', 'Enormous vastness', NULL),
(294, 1, 55, 386, 'Finland', 'MTV Katsomo', 'Älykääpio remmissä', 'Half-wit in the group', NULL),
(295, 1, 55, 387, 'Finland', 'MTV Katsomo', 'Murusia rintsikoissa', 'Crumbs in the bra', NULL),
(296, 1, 55, 388, 'Finland', 'MTV Katsomo', 'Ranskis Turpasauna', 'Chip Beating', 'What they\'ve apparently done here is literally translate the name \'Chip\' into \'chip\' (as in \'fried potato chip\'), and then converted the onomatopoeiac \'Biff\' at the start of the name \'Biffington\' into the word for \'beating\' (as in \'beating up\'). Weird that they didn\'t leave the episode title as it was, since it\'s a character\'s name.'),
(297, 1, 55, 389, 'Finland', 'MTV Katsomo', 'Pitkäjalkainen hummeri', 'Long-legged lobster', NULL),
(298, 1, 55, 390, 'Finland', 'MTV Katsomo', 'Loputtomien lautasten järjestelmä', 'The system of endless plates', NULL),
(299, 1, 55, 391, 'Finland', 'MTV Katsomo', 'Se, mitä lepakot tekevät', 'What bats do', NULL),
(300, 1, 55, 392, 'Finland', 'MTV Katsomo', 'Uusi käyttöpää', 'New operating end', NULL),
